 16	function getTTL(contentType) {
 17	  if (!contentType) return SIGNED_URL_TTL.default;
 18	  if (contentType.startsWith('image/')) return SIGNED_URL_TTL.image;
 19	  if (contentType.startsWith('video/')) return SIGNED_URL_TTL.video;
 20	  return SIGNED_URL_TTL.document;
 21	}
