 27	function buildStorageKey(binderId, attachmentId, filename) {
 28	  const now = new Date();
 29	  const yyyy = now.getFullYear();
 30	  const mm = String(now.getMonth() + 1).padStart(2, '0');
 31	  const ext = filename ? filename.split('.').pop() : '';
 32	  return `attachments/${binderId}/${yyyy}/${mm}/${attachmentId}${ext ? '.' + ext : ''}`;
 33	}
