 35	class MediaService {
 36	  /**
 37	   * context_type: SECTION_MESSAGE | EVENT | TASK | POST | CAST | avatar | cover
 38	   * context_id: UUID of the context entity
 39	   * binder_id: UUID — required for non-avatar/cover contexts
 40	   */
 41	  async presign(data, context) {
 42	    const { filename, content_type, file_size, context_type, context_id, binder_id } = data;
 43	    const id = generateUUID();
 44	
 45	    if (context_type === 'SECTION_MESSAGE') {
 46	      const sectionId = await SectionDAO.findSectionIdByMessage(pool, context_id);
 47	      if (!sectionId || !(await SectionDAO.hasAccess(pool, sectionId, context.sender_id))) {
 48	        throw new ForbiddenError('섹션 첨부 접근 권한이 없습니다', 'SECTION_ACCESS_DENIED');
 49	      }
 50	    }
 51	
 52	    let storage_key;
 53	    if (context_type === 'avatar' || context_type === 'cover') {
 54	      // Avatar/cover use entity-centric path
 55	      storage_key = `${context_type}s/${context_id}/${id}${filename ? '.' + filename.split('.').pop() : ''}`;
 56	    } else {
 57	      if (!binder_id) throw new Error('binder_id required for attachment contexts');
 58	      storage_key = buildStorageKey(binder_id, id, filename);
 59	    }
 60	
 61	    const bucket = storage.bucket(getMediaBucket());
 62	    const file = bucket.file(storage_key);
 63	
 64	    const [uploadUrl] = await file.generateSignedPostPolicyV4({
 65	      expires: Date.now() + 15 * 60 * 1000,
 66	      conditions: [
 67	        ['content-length-range', 1, 5 * 1024 * 1024 * 1024], // max 5GB
 68	        ['starts-with', '$Content-Type', ''],
 69	      ],
 70	      fields: { 'Content-Type': content_type },
 71	    });
 72	
 73	    if (context_type !== 'avatar' && context_type !== 'cover') {
 74	      await pool.query(
 75	        `INSERT INTO attachments
 76	           (id, binder_id, context_type, context_id, storage_key, filename,
 77	            file_size, content_type, status, storage_class, uploader_id,
 78	            created_at, updated_at)
 79	         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'pending','standard',$9,now(),now())`,
 80	        [id, binder_id, context_type, context_id || null,
 81	         storage_key, filename || null, file_size || null,
 82	         content_type || null, context.sender_id]
 83	      );
 84	    }
 85	
 86	    return { id, upload_url: uploadUrl, storage_key };
 87	  }
