102	  async getSignedUrl(attachmentId, userId) {
103	    const result = await pool.query(
104	      `SELECT id, storage_key, content_type, status, context_type, context_id FROM attachments WHERE id = $1`,
105	      [attachmentId]
106	    );
107	    const attachment = result.rows[0];
108	    if (!attachment) throw new NotFoundError('첨부 파일을 찾을 수 없습니다');
109	    if (attachment.context_type === 'SECTION_MESSAGE') {
110	      const sectionId = await SectionDAO.findSectionIdByMessage(pool, attachment.context_id);
111	      if (!sectionId || !(await SectionDAO.hasAccess(pool, sectionId, userId))) {
112	        throw new ForbiddenError('섹션 첨부 접근 권한이 없습니다', 'SECTION_ACCESS_DENIED');
113	      }
114	    }
115	    if (attachment.status === 'hidden') throw new ForbiddenError('잠긴 파일입니다. Boost로 복원하세요.');
116	    if (attachment.status === 'rejected') throw new ForbiddenError('접근할 수 없는 파일입니다');
117	
118	    const ttl = getTTL(attachment.content_type);
119	    const bucket = storage.bucket(getMediaBucket());
120	    const file = bucket.file(attachment.storage_key);
121	
122	    const [url] = await file.getSignedUrl({
123	      version: 'v4',
124	      action: 'read',
125	      expires: Date.now() + ttl * 1000,
126	    });
127	
128	    return { url, expires_in: ttl };
129	  }
