154	  async restoreBinderAttachments(binderId) {
155	    const result = await pool.query(
156	      `SELECT id, storage_key, storage_class FROM attachments
157	       WHERE binder_id = $1 AND status = 'hidden' AND deleted_at IS NULL`,
158	      [binderId]
159	    );
160	    const rows = result.rows;
161	    if (rows.length === 0) return 0;
162	
163	    const bucket = storage.bucket(getMediaBucket());
164	
165	    await Promise.allSettled(
166	      rows.map(async (att) => {
167	        const file = bucket.file(att.storage_key);
168	        if (att.storage_class === 'archive') {
169	          // GCS Archive restore requires a rewrite to Standard
170	          await file.copy(file, { storageClass: 'STANDARD' });
171	        } else if (att.storage_class !== 'standard') {
172	          await file.copy(file, { storageClass: 'STANDARD' });
173	        }
174	      })
175	    );
176	
177	    const ids = rows.map((r) => r.id);
178	    await pool.query(
179	      `UPDATE attachments
180	       SET status = 'ready', storage_class = 'standard', hidden_at = NULL, updated_at = now()
181	       WHERE id = ANY($1)`,
182	      [ids]
183	    );
184	
185	    return ids.length;
186	  }
